"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["45043"],{25647(e){e.exports=JSON.parse('{"id":"F443","slug":"foreign-project-npv","name":"Foreign Project NPV: Two Equivalent Methods","subject":"International Finance","section":"Global Finance","topic":"International capital budgeting","level":"Intermediate","aliases":["international capital budgeting","NPV in home currency","foreign currency discount rate","project in another country"],"formula":{"latex":"NPV=\\\\sum_{t}\\\\frac{CF^{f}_{t}\\\\,S_{t}}{(1+k_{d})^{t}}=S_{0}\\\\sum_{t}\\\\frac{CF^{f}_{t}}{(1+k_{f})^{t}},\\\\quad 1+k_{f}=(1+k_{d})\\\\frac{1+\\\\pi_{f}}{1+\\\\pi_{d}}","also":[],"text":"Method 1: convert each foreign cash flow at its expected spot rate and discount at the home required return. Method 2: discount the foreign cash flows at the foreign required return, then convert the NPV at today\'s spot. Expected spot S_t = S_0 x ((1 + home inflation) / (1 + foreign inflation))^t; Foreign required return = (1 + home) x (1 + foreign inflation) / (1 + home inflation) - 1"},"symbols":[{"symbol":"CF^f_t","meaning":"Project cash flow in foreign currency in year t","unit":"money"},{"symbol":"S_t","meaning":"Expected spot rate (home per foreign) in year t","unit":"rate"},{"symbol":"k_d, k_f","meaning":"Required return in home and in foreign currency","unit":"percent"},{"symbol":"pi_d, pi_f","meaning":"Inflation at home and abroad","unit":"percent"}],"when_to_use":"Use it to value a project abroad from the parent\'s point of view. The two methods give the same answer if the expected exchange rate follows the inflation gap (relative PPP) and the discount rates are linked by the Fisher relation. Differences arise when the currency is expected to move differently, and country risk must be added to the discount rate or to the cash flows, not both. Blocked funds or taxes on remittances also change the home cash flows.","worked_example":{"problem":"A project in a high-inflation country has cash flows of -20,000, 8,000, 10,000 and 12,000 in local currency. Spot is 0.05 USD per local unit. Inflation is 2% in the US and 6% locally. The US required return is 9%.","inputs":{"cf":[-20000,8000,10000,12000],"s0":0.05,"pd":2,"pf":6,"k":9},"steps":[{"label":"Expected spot rates, years 0 to n","working":null,"value":"0.0500, 0.0481, 0.0463, 0.0446"},{"label":"Expected spot in the last year","working":null,"value":"0.04455"},{"label":"Cash flows in USD","working":null,"value":"-1,000.00, 384.91, 462.98, 534.61"},{"label":"NPV, method 1: USD flows at the US required return","working":null,"value":"155.62"},{"label":"Local required return = (1 + k)(1 + local inflation) / (1 + US inflation) - 1","working":"(1+0.09) x (1+0.06) / (1+0.02)-1","value":"13.275%"},{"label":"NPV, method 2: local flows at the local rate, converted at spot","working":null,"value":"155.62"},{"label":"Positive NPV? (1 = yes, 0 = no)","working":"1 if 155.616>0 else 0","value":"1"}],"answer":"The expected exchange rate falls from 0.0500 to 0.04455 by year 3. Converting the flows and discounting at 9% gives an NPV of 155.62. The local required return is 13.275%, and discounting the local flows and converting at spot gives 155.62, the same answer. The positive-NPV flag is 1 (1 = the project creates value)."},"calculator":{"available":true,"inputs":[{"id":"cf","label":"Project cash flows in local currency, from year 0","unit":"money","type":"list","default":[-20000,8000,10000,12000],"hint":""},{"id":"s0","label":"Spot rate (USD per local unit)","unit":"","type":"number","default":0.05,"hint":""},{"id":"pd","label":"US inflation","unit":"%","type":"number","default":2,"hint":""},{"id":"pf","label":"Local inflation","unit":"%","type":"number","default":6,"hint":""},{"id":"k","label":"US required return","unit":"%","type":"number","default":9,"hint":""}],"checks":[{"expr":"count(cf)>=2 and s0>0","message":"Enter at least two cash flows and a spot rate above zero."}],"steps":[{"id":"path","label":"Expected spot rates, years 0 to n","expr":"fxpath(s0, pd, pf, count(cf)-1)","format":"list4"},{"id":"slast","label":"Expected spot in the last year","expr":"last(path,1)[0]","format":"num5"},{"id":"usdcf","label":"Cash flows in USD","expr":"multiply(cf, path)","format":"list2"},{"id":"npv1","label":"NPV, method 1: USD flows at the US required return","expr":"npv(k, usdcf)","format":"money"},{"id":"kf","label":"Local required return = (1 + k)(1 + local inflation) / (1 + US inflation) - 1","expr":"(1+k)*(1+pf)/(1+pd)-1","format":"pct3"},{"id":"npv2","label":"NPV, method 2: local flows at the local rate, converted at spot","expr":"npv(kf, cf)*s0","format":"money"},{"id":"ok_","label":"Positive NPV? (1 = yes, 0 = no)","expr":"1 if npv1>0 else 0","format":"num0"}],"results":["npv1","kf","npv2"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"slast":0.04455053500540715,"npv1":155.6164661820079,"kf":0.13274509803921597,"npv2":155.61646618200749,"ok_":1}},"finder":{"finds":"A foreign project\'s value to the parent company, by two routes","needs":"Local cash flows, spot, inflation, home required return"},"related":[{"slug":"npv","name":"Net Present Value (NPV)"},{"slug":"fx-forward-points","name":"Forward Exchange Rate and Forward Points"},{"slug":"country-risk-premium","name":"Country Risk Premium"}],"related_ids":["F028","F433","F167"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>N</mi><mi>P</mi><mi>V</mi><mo>=</mo><munder><mo>\u2211</mo><mi>t</mi></munder><mfrac><mrow><mi>C</mi><msubsup><mi>F</mi><mi>t</mi><mi>f</mi></msubsup><mtext>\u2009</mtext><msub><mi>S</mi><mi>t</mi></msub></mrow><mrow><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>k</mi><mi>d</mi></msub><msup><mo stretchy=\\"false\\">)</mo><mi>t</mi></msup></mrow></mfrac><mo>=</mo><msub><mi>S</mi><mn>0</mn></msub><munder><mo>\u2211</mo><mi>t</mi></munder><mfrac><mrow><mi>C</mi><msubsup><mi>F</mi><mi>t</mi><mi>f</mi></msubsup></mrow><mrow><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>k</mi><mi>f</mi></msub><msup><mo stretchy=\\"false\\">)</mo><mi>t</mi></msup></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mn>1</mn><mo>+</mo><msub><mi>k</mi><mi>f</mi></msub><mo>=</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>k</mi><mi>d</mi></msub><mo stretchy=\\"false\\">)</mo><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>\u03C0</mi><mi>f</mi></msub></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>\u03C0</mi><mi>d</mi></msub></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">NPV=\\\\sum_{t}\\\\frac{CF^{f}_{t}\\\\,S_{t}}{(1+k_{d})^{t}}=S_{0}\\\\sum_{t}\\\\frac{CF^{f}_{t}}{(1+k_{f})^{t}},\\\\quad 1+k_{f}=(1+k_{d})\\\\frac{1+\\\\pi_{f}}{1+\\\\pi_{d}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"forecast-calibration","name":"Forecast Calibration and Brier Score"},"next":{"slug":"forward-contract-value","name":"Forward Contract: Fair Price, Value and Payoff"},"lesson":null,"total":522}')}}]);